  &reftitle.examples;

   Exemplo de Yaf_Controller_Abstract::forward


<?php
class IndexController extends Yaf_Controller_Abstract
{
    public function indexAction() {
        $logined = $_SESSION["login"];
        if (!$logined) {
            $this->forward("login", array("from" => "Index")); // encaminha para a ação de login
            return false; // isto é importante, encerra o fluxo atual
                          // e informa ao Yaf para não renderizar automaticamente
        }

        // outros processos
    }

    public function loginAction() {
        echo "login, redirected from ", $this->_request->getParam("from") , " action";
    }
}
?>


   &example.outputs.similar;


   login, redirecionado da ação Index
